import{_ as t,o as a,c as i,a6 as s}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"Présentation du développement de plugins","description":"","frontmatter":{"title":"Présentation du développement de plugins","docId":"developer.plugins.index","translationKey":"developer.plugins.index","locale":"fr","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"690689449dfe463405cff0ea6b3a33979249bbe68c598ee7e8ca862eedd704dc","translationRevision":"e6944721411c494b9a2398b6b304b0db7cde920620761307d4046e42bfbad226","order":240},"headers":[],"relativePath":"fr/developer/plugins/index.md","filePath":"fr/developer/plugins/index.md","lastUpdated":1794611623000}'),n={name:"fr/developer/plugins/index.md"};function r(o,e,l,d,p,c){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="plugin-development-overview" tabindex="-1">Présentation du développement de plugins <a class="header-anchor" href="#plugin-development-overview" aria-label="Permalink to &quot;Présentation du développement de plugins {#plugin-development-overview}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Choisir la plus petite frontière de plugin répondant à votre intégration. TikTools découvre les paquets d’exécution depuis les racines intégrées, utilisateur et de développement ; ajouter un paquet ne nécessite pas de recompiler un plugin nommé dans l’hôte. Utilisez le kit de développement/SDK correspondant et un profil privé de développement avant de tester des effets.</p><h2 id="follow-the-authoring-path" tabindex="-1">Suivre le parcours de création <a class="header-anchor" href="#follow-the-authoring-path" aria-label="Permalink to &quot;Suivre le parcours de création {#follow-the-authoring-path}&quot;">​</a></h2><ol><li>Commencez par le <a href="./quickstart.html">démarrage rapide</a> pour générer, valider et compiler un paquet isolé.</li><li>Choisissez un <a href="./runtimes.html">environnement d’exécution</a> selon les dépendances natives et la confiance, pas seulement l’extension du fichier.</li><li>Déclarez les <a href="./permissions-ui.html">permissions et l’interface</a> pour que l’hôte puisse examiner les effets et afficher la configuration.</li><li>Consultez l’<a href="./packaging-registry.html">empaquetage et le registre</a> pour l’intégrité, la confiance de l’éditeur et la politique de mise à jour.</li></ol><p>L’autorité Rust de bas niveau est <code>crates/tiktools-plugin-api</code> : validation du manifeste, protocole et contrats d’interface. <code>crates/tiktools-plugin-sdk</code> fournit l’interface de création Rust ; <code>packages/plugin-sdk</code> contient les utilitaires TypeScript et le <a href="https://github.com/nglmercer/TikTools-app/blob/remake/packages/plugin-sdk/plugin.schema.json" target="_blank" rel="noreferrer">schéma pour l’éditeur</a>. Le chargement à l’exécution appartient à <code>crates/tiktools-plugin-loader</code>, pas à l’interface.</p><h2 id="understand-contributions" tabindex="-1">Comprendre les contributions <a class="header-anchor" href="#understand-contributions" aria-label="Permalink to &quot;Comprendre les contributions {#understand-contributions}&quot;">​</a></h2><p>Une action demande un effet via un résultat typé. Les sources d’événements publient des déclencheurs ; les observateurs reçoivent des enveloppes métier stables <code>{topic,data}</code> avec livraison bornée. Les processeurs ajoutent des éléments sans effet sous <code>event.intel</code>, avec échéances, fusion déterministe et isolation des défaillances. Les paramètres/actions déclaratifs permettent à l’hôte d’afficher une configuration ordinaire. Une page compilée personnalisée utilise un courtier de plugin restreint dans son propre cadre/fenêtre ; son script ne fait jamais partie du runtime Vue principal.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-plugin-api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>Ce sont des vérifications ciblées hôte/SDK, pas la validation d’un paquet externe arbitraire.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>Les parcours natif, processus, déclaratif et <code>napi-vm</code> fondé sur QuickJS sont implémentés. WASM est un emplacement d’exécution facultatif sans moteur général actif dans les compilations normales. Les intégrations d’exemple se trouvent dans le <a href="https://github.com/nglmercer/plugins-example-tiktools" target="_blank" rel="noreferrer">dépôt distinct plugins-example-tiktools</a> ; les noms de sources dans les anciens documents n’en font pas des fonctions produit embarquées.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>En cas d’échec de découverte, examinez la compatibilité du manifeste, la priorité des racines, la cible et le chemin d’entrée. Pour une intention refusée, examinez les capacités déclarées et accordées au lieu de contourner l’hôte. Un démarrage incertain doit être résolu avant remplacement. Les frontières natives/processus conservent les limites de confiance du système ; le nom de l’environnement ne prouve jamais l’existence d’un bac à sable.</p>`,14)])])}const m=t(n,[["render",r]]);export{h as __pageData,m as default};
